{
  "command": "replace_content_by_matching",
  "args": {
    "old_content": "    // Interface mapping (since encoding is described as y[5:0] for A..F):
    // interface y[1] -> internal y[0] (A)
    // interface y[2] -> internal y[1] (B)
    // interface y[3] -> internal y[2] (C)
    // interface y[4] -> internal y[3] (D)
    // interface y[5] -> internal y[4] (E)
    // interface y[6] -> internal y[5] (F)

    logic yA, yB, yC, yD, yE, yF;

    always @(*) begin
        yA = y[1];
        yB = y[2];
        yC = y[3];
        yD = y[4];
        yE = y[5];
        yF = y[6];

        // Next-state equations derived by inspection
        // Y2 is next-state for B: only A --0--> B
        Y2 = yA & ~w;

        // Y4 is next-state for D: B,C,E,F all go to D when w=1
        Y4 = (yB | yC | yE | yF) & w;
    end
",
    "new_content": "    // One-hot encoding (interface y[6:1]):
    // y[1]=A, y[2]=B, y[3]=C, y[4]=D, y[5]=E, y[6]=F

    logic yA, yB, yC, yE, yF;

    always_comb begin
        yA = y[1];
        yB = y[2];
        yC = y[3];
        yE = y[5];
        yF = y[6];

        // Next-state outputs (Y2 corresponds to next-state B, Y4 corresponds to next-state D)
        Y2 = yA & ~w;                         // A --0--> B
        Y4 = (yB | yC | yE | yF) & w;       // B,C,E,F --1--> D
    end
"
  }
}

